import { divisions } from '@mintlify/validation';
const isRecord = (value) => typeof value === 'object' && value !== null && !Array.isArray(value);
const getString = (record, key) => {
    const value = record[key];
    return typeof value === 'string' && value.trim() ? value.trim() : undefined;
};
function collectPages(entry, pages) {
    if (Array.isArray(entry)) {
        entry.forEach((item) => collectPages(item, pages));
        return;
    }
    if (!isRecord(entry))
        return;
    const href = getString(entry, 'href');
    const title = getString(entry, 'sidebarTitle') ?? getString(entry, 'title');
    if (href && title && 'title' in entry) {
        if (href.startsWith('/') && !href.startsWith('//') && !pages.has(href)) {
            pages.set(href, { title, href, description: getString(entry, 'description') });
        }
        return;
    }
    for (const key of ['root', 'pages', 'groups', ...divisions]) {
        collectPages(entry[key], pages);
    }
}
const escapeLinkText = (text) => text.replace(/([[\]])/g, '\\$1');
export function generateExportLlmsTxt(docsConfig, generatedNav, routes, basePath = '') {
    const config = isRecord(docsConfig) ? docsConfig : {};
    const name = getString(config, 'name') ?? 'Documentation';
    const description = getString(config, 'description');
    const pages = new Map();
    collectPages(generatedNav, pages);
    const header = `# ${name}\n${description ? `\n> ${description}\n` : ''}\n## Docs\n\n`;
    const exportedRoutes = new Set(routes);
    const lines = [...pages.values()]
        .filter((page) => exportedRoutes.has(page.href))
        .map((page) => `- [${escapeLinkText(page.title)}](${basePath}${page.href})${page.description ? `: ${page.description}` : ''}\n`);
    return header + lines.join('');
}
